import{_ as a,o as d,c as o,a5 as r}from"./chunks/framework.BqnnR8ku.js";const u=JSON.parse('{"title":"项目管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/projects.md","filePath":"zh/guide/projects.md"}'),l={name:"zh/guide/projects.md"};function e(i,t,s,n,h,c){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="项目管理" tabindex="-1">项目管理 <a class="header-anchor" href="#项目管理" aria-label="Permalink to &quot;项目管理&quot;">​</a></h1><p>项目是组织一次翻译工作的基本单位：语言方向、源文件（资源）、术语表与翻译作业都挂在项目下。</p><p>尚未跑通第一次翻译？请先看 <a href="/LinguaFlow/zh/guide/getting-started.html">快速开始 · Web</a>。名词解释见 <a href="/LinguaFlow/zh/guide/concepts.html">核心概念</a>。</p><h2 id="创建项目" tabindex="-1">创建项目 <a class="header-anchor" href="#创建项目" aria-label="Permalink to &quot;创建项目&quot;">​</a></h2><ol><li>打开 <strong>项目</strong> 页，点击 <strong>新建项目</strong></li><li>填写项目信息： <ul><li><strong>项目名称</strong> — 用于标识项目（最多 80 个字符）</li><li><strong>源语言</strong> — 源文件语言，可用 <code>auto</code> 自动识别</li><li><strong>目标语言</strong> — 要译成的语言</li><li><strong>启用术语表</strong> — 是否在翻译时应用术语规则</li></ul></li><li>点击 <strong>创建</strong>，再点进项目卡片进入工作区</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>创建后可随时改名称、语言与术语表开关。本地模式下你就是唯一用户，无需关心组织归属。</p></div><h3 id="支持的语言-节选" tabindex="-1">支持的语言（节选） <a class="header-anchor" href="#支持的语言-节选" aria-label="Permalink to &quot;支持的语言（节选）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>代码</th><th>语言</th></tr></thead><tbody><tr><td><code>auto</code></td><td>自动识别（仅限源语言）</td></tr><tr><td><code>zh-Hans</code></td><td>简体中文</td></tr><tr><td><code>zh-Hant</code></td><td>繁体中文</td></tr><tr><td><code>en-US</code></td><td>英语（美国）</td></tr><tr><td><code>en-GB</code></td><td>英语（英国）</td></tr><tr><td><code>ja</code></td><td>日语</td></tr><tr><td><code>ko</code></td><td>韩语</td></tr><tr><td><code>fr</code></td><td>法语</td></tr><tr><td><code>de</code></td><td>德语</td></tr><tr><td><code>es</code></td><td>西班牙语</td></tr></tbody></table><p>界面中通常提供更完整的语言列表。</p><h3 id="项目归属-服务器模式-·-预览" tabindex="-1">项目归属（服务器模式 · 预览） <a class="header-anchor" href="#项目归属-服务器模式-·-预览" aria-label="Permalink to &quot;项目归属（服务器模式 · 预览）&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">预览</p><p>组织与多用户归属依赖服务器模式，该模式仍在完善。个人本地使用时只需个人项目即可。</p></div><ul><li><strong>个人项目</strong> — 归属当前用户</li><li><strong>组织项目</strong> — 归属组织（需相应权限）</li></ul><h2 id="项目列表" tabindex="-1">项目列表 <a class="header-anchor" href="#项目列表" aria-label="Permalink to &quot;项目列表&quot;">​</a></h2><p>首页展示所有项目列表，支持以下功能：</p><ul><li><strong>搜索过滤</strong> — 按项目名称或语言代码搜索</li><li><strong>统计面板</strong> — 显示全部项目数和语言方向数</li><li><strong>排序</strong> — 按更新时间降序排列</li><li><strong>快捷操作</strong> — 右键菜单可查看详情、编辑、查看任务、管理术语表或删除项目</li></ul><h2 id="项目工作区" tabindex="-1">项目工作区 <a class="header-anchor" href="#项目工作区" aria-label="Permalink to &quot;项目工作区&quot;">​</a></h2><p>进入项目后，顶部显示项目基本信息（名称、语言方向、更新时间）和统计指标栏：</p><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>资源数</td><td>项目中的文件总数</td></tr><tr><td>段落数</td><td>待翻译的内容段总数</td></tr><tr><td>已翻译</td><td>已完成翻译的段落数</td></tr><tr><td>已审核</td><td>已通过审核的段落数</td></tr><tr><td>运行中作业</td><td>正在执行的翻译作业数</td></tr></tbody></table><p>工作区包含四个标签页：</p><ol><li><strong>资源文件</strong> — 文件管理（详见下方）</li><li><strong>段落编辑</strong> — 翻译内容查看与编辑，支持按原文/译文搜索；段落行操作菜单可发起 <a href="/LinguaFlow/zh/guide/translation-config.html#单段试译">单段试译预览</a> / <a href="/LinguaFlow/zh/guide/translation-config.html#单段修订预览">单段修订预览</a>，满意后再应用译文；工具栏可发起 <a href="/LinguaFlow/zh/guide/review.html#搜索替换">搜索替换</a> 对译文批量查找替换</li><li><strong>翻译作业</strong> — 翻译作业管理（详见下方）</li><li><strong>术语表</strong> — 项目术语管理</li></ol><h2 id="管理翻译资源" tabindex="-1">管理翻译资源 <a class="header-anchor" href="#管理翻译资源" aria-label="Permalink to &quot;管理翻译资源&quot;">​</a></h2><h3 id="上传文件" tabindex="-1">上传文件 <a class="header-anchor" href="#上传文件" aria-label="Permalink to &quot;上传文件&quot;">​</a></h3><p>支持以下方式上传文件：</p><ul><li><strong>拖拽上传</strong> — 将文件拖拽到上传区域</li><li><strong>点击上传</strong> — 点击上传按钮，通过系统文件选择器一次选取多个文件</li><li><strong>批量上传</strong> — 一次最多上传 50 个文件</li></ul><p>一次选择多个文件时，会合并为一个<strong>批次任务</strong>：上传面板按批次展示任务，而不是每个文件各占一条；状态摘要与进度按批次内文件数汇总（如「正在上传 3 个文件」），展开面板可见每个批次任务的文件名、所处阶段、上传百分比或错误信息。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>上传前会自动进行冲突检测。如果同名文件已存在，可选择替换或增量更新。</p></div><h3 id="支持的文件格式" tabindex="-1">支持的文件格式 <a class="header-anchor" href="#支持的文件格式" aria-label="Permalink to &quot;支持的文件格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>扩展名</th><th>说明</th></tr></thead><tbody><tr><td>Markdown</td><td><code>.md</code>, <code>.markdown</code>, <code>.mdx</code></td><td>通用文档格式</td></tr><tr><td>HTML</td><td><code>.html</code>, <code>.htm</code></td><td>标记语言文档</td></tr><tr><td>DOCX</td><td><code>.docx</code></td><td>Word 文档</td></tr><tr><td>EPUB</td><td><code>.epub</code></td><td>电子书格式</td></tr><tr><td>SRT</td><td><code>.srt</code></td><td>字幕格式</td></tr><tr><td>VTT</td><td><code>.vtt</code></td><td>Web 字幕格式</td></tr><tr><td>ASS</td><td><code>.ass</code></td><td>高级字幕格式</td></tr><tr><td>纯文本</td><td><code>.txt</code></td><td>纯文本文件</td></tr><tr><td>JSON</td><td><code>.json</code></td><td>JSON 结构化格式</td></tr><tr><td>YAML</td><td><code>.yaml</code>, <code>.yml</code></td><td>YAML 结构化格式</td></tr><tr><td>TOML</td><td><code>.toml</code></td><td>TOML 结构化格式</td></tr></tbody></table><p>详见 <a href="/LinguaFlow/zh/guide/formats.html">格式支持</a>。</p><h3 id="资源管理" tabindex="-1">资源管理 <a class="header-anchor" href="#资源管理" aria-label="Permalink to &quot;资源管理&quot;">​</a></h3><p>上传后的资源可以进行以下操作：</p><ul><li><strong>查看</strong> — 浏览源文件内容</li><li><strong>翻译</strong> — 启动翻译作业</li><li><strong>替换</strong> — 上传新文件替换已有资源</li><li><strong>增量更新</strong> — 在保留已有翻译的基础上更新源文件</li><li><strong>下载</strong> — 下载原始文件或翻译结果文件</li><li><strong>删除</strong> — 删除资源及其所有段落和翻译</li></ul><h3 id="epub-特殊支持" tabindex="-1">EPUB 特殊支持 <a class="header-anchor" href="#epub-特殊支持" aria-label="Permalink to &quot;EPUB 特殊支持&quot;">​</a></h3><p>EPUB 格式文件具有专用的虚拟目录结构和章节导航，支持按章节选择翻译。若需统一全书横排/竖排，可使用 Web <strong>工具 → EPUB 横竖排转换</strong>（本机处理、不上传），见 <a href="/LinguaFlow/zh/guide/formats.html#epub-电子书">格式支持 · EPUB</a>。</p><h2 id="翻译作业" tabindex="-1">翻译作业 <a class="header-anchor" href="#翻译作业" aria-label="Permalink to &quot;翻译作业&quot;">​</a></h2><h3 id="创建翻译作业" tabindex="-1">创建翻译作业 <a class="header-anchor" href="#创建翻译作业" aria-label="Permalink to &quot;创建翻译作业&quot;">​</a></h3><ol><li>在项目中选择需要翻译的资源（或资源中的特定段落/章节）</li><li>选择翻译执行计划</li><li>配置作业参数： <ul><li><strong>过滤配置</strong> — 控制对已有翻译的处理方式</li><li><strong>自动审核</strong> — 翻译完成后是否自动标记为已审核</li></ul></li><li>点击 <strong>开始翻译</strong></li></ol><h3 id="过滤配置" tabindex="-1">过滤配置 <a class="header-anchor" href="#过滤配置" aria-label="Permalink to &quot;过滤配置&quot;">​</a></h3><p>创建作业时可配置段落过滤，控制哪些段落需要重新翻译：</p><table tabindex="0"><thead><tr><th>过滤选项</th><th>说明</th></tr></thead><tbody><tr><td>跳过已批准</td><td>跳过已审批通过的段落（默认）</td></tr><tr><td>覆盖未批准</td><td>覆盖所有未审批通过的段落</td></tr><tr><td>覆盖全部</td><td>覆盖所有段落，无论状态</td></tr></tbody></table><p>过滤配置可在执行计划中预设默认值，创建作业时按需覆盖。</p><h3 id="作业状态" tabindex="-1">作业状态 <a class="header-anchor" href="#作业状态" aria-label="Permalink to &quot;作业状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>等待中</td><td>作业已创建，等待执行</td></tr><tr><td>运行中</td><td>正在进行翻译</td></tr><tr><td>已暂停</td><td>被手动暂停，可随时恢复（见下方）</td></tr><tr><td>已完成</td><td>翻译完成</td></tr><tr><td>失败</td><td>翻译失败，可查看错误信息或重试</td></tr><tr><td>已取消</td><td>用户手动取消的作业</td></tr></tbody></table><h3 id="暂停与恢复" tabindex="-1">暂停与恢复 <a class="header-anchor" href="#暂停与恢复" aria-label="Permalink to &quot;暂停与恢复&quot;">​</a></h3><p>任务列表和任务详情抽屉中提供 <strong>暂停</strong> / <strong>恢复</strong> 操作：</p><ul><li><strong>暂停</strong>（等待中、运行中可用）— 优雅暂停：停止派发新批次，等待在途请求完成后冻结任务。运行中的任务需要等在途 LLM 请求收尾，界面短暂仍显示「运行中」属正常现象；等待中的任务立即变为「已暂停」</li><li><strong>恢复</strong>（已暂停可用）— 从轮次断点继续：已完成的轮次与段落直接跳过，进度计数保留，不会从头重跑</li><li>暂停不会清零进度——界面保留已完成的工作量百分比，并显示「已暂停，可随时恢复」</li><li>已暂停的任务仍可<strong>取消</strong>；暂停与取消互不替代：暂停是可恢复的中断，取消是终态（但失败/取消的任务也能通过「重试」从断点继续）</li></ul><div class="info custom-block"><p class="custom-block-title">什么场景适合暂停</p><p>LLM 速率限额即将耗尽、需要临时让出本机资源、或想在夜间低谷再继续——暂停让任务停在轮次断点，恢复后从同一位置继续，已产出译文不受影响。</p></div><h3 id="进度追踪" tabindex="-1">进度追踪 <a class="header-anchor" href="#进度追踪" aria-label="Permalink to &quot;进度追踪&quot;">​</a></h3><p>翻译过程中通过 SSE 实时推送进度信息（支持断线重连、事件持久化）：</p><ul><li><strong>翻译进度</strong> — 已完成工作量 / 总工作量（单位为「段 × 轮」，见下方「进度口径」）</li><li><strong>预计剩余时间 (ETA)</strong></li><li><strong>当前翻译速度</strong></li><li><strong>事件序号（seq）</strong> — 保证事件顺序，重连后可精准恢复丢失的事件</li></ul><h4 id="进度口径-工作量而非段落数" tabindex="-1">进度口径：工作量而非段落数 <a class="header-anchor" href="#进度口径-工作量而非段落数" aria-label="Permalink to &quot;进度口径：工作量而非段落数&quot;">​</a></h4><p>主进度按「工作量」统计：分母是已启动轮次的工作量总和（每轮 × 该轮段落数），分子是已完成部分。两点推论：</p><ul><li><strong>新轮次启动时百分比可能暂时回落</strong>——分母只计入已经启动并得知规模的轮次，后续轮次启动会扩大分母</li><li><strong>失败、取消、暂停的任务仍显示停下时的真实比例</strong>，不会归零或冻结在旧值</li></ul><h4 id="轮次矩阵" tabindex="-1">轮次矩阵 <a class="header-anchor" href="#轮次矩阵" aria-label="Permalink to &quot;轮次矩阵&quot;">​</a></h4><p>任务详情（桌面端）的资源表提供「资源行 × 轮次列」矩阵：列标题为该轮的模式（翻译、语义质检等），单元格展示该资源在该轮的待执行 / 执行中 / 完成 / 失败 / 跳过计数，悬停可查看轮次序号、段落数、起止时间与错误信息。任务详情顶部的进度卡还会为未完成任务展示按轮次聚合的管线条，方便定位任务停在哪个环节。移动端资源表仅保留资源名称与状态。</p><p>作业详情中的 <strong>事件时间线</strong> 会把这些事件按 <code>seq</code> 顺序铺成一条可滚动的时间线：</p><ul><li><strong>实时</strong> — 作业运行期间通过 SSE 推送新事件，自动追加到底部</li><li><strong>历史分页</strong> — 进入一个已结束的作业时，从 REST 历史端点拉取最近一页事件；向上滚动到顶部时可 <strong>下拉加载更早的事件</strong></li><li><strong>批次事件卡</strong> — 每个批次翻译事件以卡片形式展示状态与摘要，<strong>点击卡片</strong> 打开右侧 <strong>批次详情抽屉</strong></li><li><strong>批次详情抽屉</strong> — 展示该批次的完整元数据：状态、错误信息、发送 / 接收内容、术语使用情况，以及截断 / 解析修复诊断标签（见 <a href="/LinguaFlow/zh/guide/review.html#截断与修复诊断">翻译审校 · 截断与修复诊断</a>），便于排错与复盘</li><li><strong>跳过状态</strong> — 因目标段状态不满足 <code>segment_filter</code> 而未执行的批次，会标记为 <code>skipped</code>（信息色），与成功 / 部分成功 / 失败区分</li></ul><div class="tip custom-block"><p class="custom-block-title">历史事件也可查询</p><p>任务事件不仅能在界面里看，也有对应的 REST 分页端点（按 <code>seq</code> 游标双向翻页），便于外部监控或导出。详见 <a href="/LinguaFlow/zh/api/#_9-任务事件历史-分页">API 概述 · 任务事件</a>。</p></div><h3 id="作业操作" tabindex="-1">作业操作 <a class="header-anchor" href="#作业操作" aria-label="Permalink to &quot;作业操作&quot;">​</a></h3><ul><li><strong>暂停 / 恢复</strong> — 见上方「暂停与恢复」</li><li><strong>取消</strong> — 取消等待中、运行中或已暂停的作业（终态）</li><li><strong>重试</strong> — 对失败或已取消的作业重新执行：失败/取消的资源重新入队，已完成轮次与已翻译段落直接跳过，从当前进度断点继续。例外：显式手选段落的任务，首个翻译轮会重译所有选中段落</li></ul><h2 id="项目设置" tabindex="-1">项目设置 <a class="header-anchor" href="#项目设置" aria-label="Permalink to &quot;项目设置&quot;">​</a></h2><h3 id="语言设置" tabindex="-1">语言设置 <a class="header-anchor" href="#语言设置" aria-label="Permalink to &quot;语言设置&quot;">​</a></h3><ul><li>修改源语言和目标语言</li><li>切换源语言自动识别</li></ul><h3 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h3><p>将术语表关联到项目，翻译时自动应用术语规则。启用后，翻译引擎会优先使用术语表中的翻译结果。</p><p>详见 <a href="/LinguaFlow/zh/guide/glossary.html">术语表管理</a>。</p><h2 id="项目删除" tabindex="-1">项目删除 <a class="header-anchor" href="#项目删除" aria-label="Permalink to &quot;项目删除&quot;">​</a></h2><p>删除项目时会<strong>级联删除</strong>以下所有关联数据：</p><ul><li>翻译作业及其关联关系</li><li>资源文件及其段落</li><li>术语表条目</li><li>翻译记忆条目</li><li>同步任务记录</li><li>活动日志和使用记录</li></ul><div class="tip custom-block"><p class="custom-block-title">活动日志的两种视角</p><p>项目内的「活动」是当前用户视角的过滤视图。服务器模式下，管理员可在 <a href="/LinguaFlow/zh/guide/admin.html#审计日志">管理员后台 · 审计日志</a> 查看全局审计记录。</p></div><div class="danger custom-block"><p class="custom-block-title">警告</p><p>项目删除操作不可撤销，请谨慎操作。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>阅读 <a href="/LinguaFlow/zh/guide/translation-config.html">翻译配置 · 使用</a> 了解如何优化翻译效果</li><li>阅读 <a href="/LinguaFlow/zh/guide/glossary.html">术语表管理</a> 了解术语管理</li><li>阅读 <a href="/LinguaFlow/zh/guide/review.html">翻译审校</a> 了解翻译质量控制</li></ul>',73)])])}const p=a(l,[["render",e]]);export{u as __pageData,p as default};
